_PremiumizeFilesScreenState.initState:
@override
  void initState() {
    super.initState();
    AnalyticsService.screenView('premiumize_files');
    _loadSettings();

    if (widget.isPushedRoute) {
      MainPageBridge.pushRouteBackHandler(_handleBackNavigation);
    } else {
      MainPageBridge.registerTabBackHandler(
        'premiumize',
        _handleBackNavigation,
      );
      _tvContentFocusHandler = () {
        _shouldFocusOnLoad = true;
        _focusFirstItemOrFallback();
      };
      MainPageBridge.registerTvContentFocusHandler(
        _tabIndex,
        _tvContentFocusHandler!,
      );
    }
  }

_PremiumizeFilesScreenState.dispose:
@override
  void dispose() {
    if (widget.isPushedRoute) {
      MainPageBridge.popRouteBackHandler(_handleBackNavigation);
    } else {
      MainPageBridge.unregisterTabBackHandler('premiumize');
      if (_tvContentFocusHandler != null) {
        MainPageBridge.unregisterTvContentFocusHandler(
          _tabIndex,
          _tvContentFocusHandler!,
        );
      }
    }
    _searchDebounce?.cancel();
    _scrollController.dispose();
    _linkController.dispose();
    _searchController.dispose();
    _refreshButtonFocusNode.dispose();
    _backButtonFocusNode.dispose();
    _retryButtonFocusNode.dispose();
    _settingsButtonFocusNode.dispose();
    _viewModeDropdownFocusNode.dispose();
    _addLinkButtonFocusNode.dispose();
    _firstItemFocusNode.dispose();
    _deleteButtonFocusNode.dispose();
    _searchFocusNode.dispose();
    _searchButtonFocusNode.dispose();
    _searchClearFocusNode.dispose();
    super.dispose();
  }

_PremiumizeFilesScreenState._loadSetting:
Future<void> _loadSettings() async {
    final enabled = await PremiumizeStorage.getPremiumizeIntegrationEnabled();
    final apiKey = await PremiumizeStorage.getPremiumizeApiKey();

    if (!mounted) return;
    setState(() {
      _premiumizeEnabled = enabled && apiKey != null && apiKey.isNotEmpty;
      _apiKey = apiKey;
      if (widget.initialFolderId != null && widget.initialFolderName != null) {
        _currentFolderId = widget.initialFolderId;
        _currentFolderName = widget.initialFolderName!;
      }
      final initialQuery = widget.initialSearchQuery?.trim() ?? '';
      if (initialQuery.isNotEmpty) {
        _isSearchActive = true;
        _searchController.text = initialQuery;
      }
    });

    if (_premiumizeEnabled) {
      _loadFolder();
      final initialQuery = widget.initialSearchQuery?.trim() ?? '';
      if (initialQuery.isNotEmpty) _performSearch(initialQuery);
    } else {
      setState(() => _initialLoad = false);
    }
  }

_PremiumizeFilesScreenState._loadFolder:
Future<void> _loadFolder() async {
    final apiKey = _apiKey;
    if (apiKey == null || apiKey.isEmpty || _isLoading) return;

    setState(() {
      _isLoading = true;
      _errorMessage = '';
    });

    try {
      final listing = await PremiumizeService.listFolder(
        apiKey,
        folderId: _currentFolderId,
      );
      if (!mounted) return;

      final mode = _getCurrentViewMode();
      final ordered = _applyViewMode(mode, listing.items);

      setState(() {
        _items
          ..clear()
          ..addAll(ordered);
        _isLoading = false;
        _initialLoad = false;
      });
      _focusFirstItemOrFallback();
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _errorMessage = e.toString();
        _isLoading = false;
        _initialLoad = false;
      });
    }
  }

_PremiumizeFilesScreenState._loadTransfe:
Future<void> _loadTransfers() async {
    final apiKey = _apiKey;
    if (apiKey == null || apiKey.isEmpty || _isLoadingTransfers) return;

    setState(() {
      _isLoadingTransfers = true;
      _errorMessage = '';
    });

    try {
      final transfers = await PremiumizeService.listTransfers(apiKey);
      if (!mounted) return;
      setState(() {
        _transfers
          ..clear()
          ..addAll(transfers);
        _isLoadingTransfers = false;
        _initialLoad = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _errorMessage = e.toString();
        _isLoadingTransfers = false;
        _initialLoad = false;
      });
    }
  }

_PremiumizeFilesScreenState._switchView:
void _switchView(_PremiumizeView view) {
    if (_selectedView == view) return;
    _exitSelectionMode();
    // Reset the Files list offset so a Files→Transfers→Files round-trip
    // doesn't land back on a stale scroll position.
    if (_scrollController.hasClients) _scrollController.jumpTo(0);
    setState(() {
      _selectedView = view;
      _errorMessage = '';
    });
    if (view == _PremiumizeView.transfers) {
      _loadTransfers();
    } else {
      _loadFolder();
    }
  }

_PremiumizeFilesScreenState._navigateInt:
void _navigateIntoFolder(PremiumizeFolderItem folder) {
    _exitSelectionMode();
    _shouldFocusOnLoad = true;
    // Reset scroll while the outgoing list is still attached, so the new
    // folder never inherits the old offset.
    if (_scrollController.hasClients) _scrollController.jumpTo(0);
    setState(() {
      _navigationStack.add((id: _currentFolderId, name: _currentFolderName));
      _currentFolderId = folder.id;
      _currentFolderName = folder.name;
      // Clear stale rows so the loading skeleton shows instead of the
      // outgoing folder's contents sitting frozen while the fetch runs.
      _items.clear();
      _isSearchActive = false;
      _searchController.clear();
      _searchResults = [];
    });
    _loadFolder();
  }

_PremiumizeFilesScreenState._navigateUp:
void _navigateUp() {
    _exitSelectionMode();
    if (_navigationStack.isEmpty) return;
    // Refocus the first row once the parent listing loads — clearing _items
    // disposes the focused row and nothing else reclaims DPAD focus.
    _shouldFocusOnLoad = true;
    if (_scrollController.hasClients) _scrollController.jumpTo(0);
    setState(() {
      final previous = _navigationStack.removeLast();
      _currentFolderId = previous.id;
      _currentFolderName = previous.name;
      _items.clear();
    });
    _loadFolder();
  }

_PremiumizeFilesScreenState._handleBackN:
bool _handleBackNavigation() {
    if (_isSelectionMode) {
      _exitSelectionMode();
      return true;
    }
    if (_isSearchActive) {
      _toggleSearch();
      return true;
    }
    if (_navigationStack.isNotEmpty) {
      _navigateUp();
      return true;
    }
    // At this folder's root (no deeper stack). If opened as a pushed route
    // (e.g. deep-linked into a specific folder), pop back to the caller.
    if (widget.isPushedRoute) {
      Navigator.of(context).pop();
      return true;
    }
    if (MainPageBridge.returnToTorrentSearchOnBack) {
      MainPageBridge.returnToTorrentSearchOnBack = false;
      MainPageBridge.switchTab?.call(MainTab.legacyTorrentSearch);
      return true;
    }
    return false;
  }

_PremiumizeFilesScreenState._selectBound:
Future<void> _selectBoundSource(PremiumizeFolderItem item) async {
    final apiKey = _apiKey;
    if (apiKey == null || apiKey.isEmpty) return;

    _showLoadingDialog(
      item.isFolder ? 'Checking folder for videos...' : 'Checking file...',
    );
    var checkingDialogOpen = true;
    void closeCheckingDialog() {
      if (!checkingDialogOpen) return;
      checkingDialogOpen = false;
      _dismissDialog();
    }

    try {
      if (item.isFolder) {
        final files = await PremiumizeService.listFolderRecursive(
          apiKey,
          item.id,
        );
        if (!mounted) return;
        final videos = files.where((f) => f.isVideo).toList();
        if (videos.isEmpty) {
          closeCheckingDialog();
          _showSnackBar('This folder has no playable videos', isError: true);
          return;
        }
        final first = videos.first;
        final firstReady =
            first.playableUrl?.isNotEmpty == true ||
            await PremiumizeService.resolveItemById(apiKey, first.id) != null;
        if (!mounted) return;
        if (!firstReady) {
          closeCheckingDialog();
          _showSnackBar(
            'This folder has no ready video streams',
            isError: true,
          );
          return;
        }
      } else {
        if (!item.isVideo) {
          closeCheckingDialog();
          _showSnackBar('Only video files can be bound', isError: true);
          return;
        }
        final resolved = await PremiumizeService.resolveItemById(
          apiKey,
          item.id,
        );
        if (resolved == null || resolved.link.isEmpty) {
          closeCheckingDialog();
          _showSnackBar('This file is not ready to stream', isError: true);
          return;
        }
      }

      closeCheckingDialog();
      await widget.onSourceSelected?.call(
        SeriesSource(
          torrentHash: '',
          torrentName: item.name,
          debridService: 'premiumize',
          debridTorrentId: item.id,
          cloudSourceKind: item.isFolder
              ? SeriesSource.cloudKindFolder
              : SeriesSource.cloudKindFile,
          boundAt: DateTime.now().millisecondsSinceEpoch,
        ),
      );
      if (!mounted) return;
      Navigator.of(context).pop();
    } catch (e) {
      closeCheckingDialog();
      if (mounted) {
        _showSnackBar(
          'Could not bind this Premiumize source: $e',
          isError: true,
        );
      }
    }
  }

_PremiumizeFilesScreenState._playFile:
Future<void> _playFile(PremiumizeFolderItem file) async {
    String? url = file.playableUrl;
    // Search hits (folder/search) may omit the direct link — resolve by id.
    if ((url == null || url.isEmpty) &&
        _apiKey != null &&
        _apiKey!.isNotEmpty) {
      final resolved = await PremiumizeService.resolveItemById(
        _apiKey!,
        file.id,
      );
      url = resolved?.link;
    }
    if (url == null || url.isEmpty) {
      _showSnackBar('No playable URL for this file', isError: true);
      return;
    }
    final sizeBytes = file.size > 0 ? file.size : null;
    if (!mounted) return;
    MainPageBridge.notifyPlayerLaunching();
    await VideoPlayerLauncher.push(
      context,
      VideoPlayerLaunchArgs(
        videoUrl: url,
        title: file.name,
        subtitle: sizeBytes != null
            ? Formatters.formatFileSize(sizeBytes)
            : null,
        playlist: [
          PlaylistEntry(
            url: url,
            title: file.name,
            relativePath: file.relativePath ?? file.name,
            provider: 'premiumize',
            premiumizeItemId: file.id,
            sizeBytes: sizeBytes,
          ),
        ],
        startIndex: 0,
      ),
    );
  }

_PremiumizeFilesScreenState._playFolder:
Future<void> _playFolder(PremiumizeFolderItem folder) async {
    final apiKey = _apiKey;
