_PremiumizeFilesScreenState._toggleSearc:
void _toggleSearch() {
    setState(() {
      _isSearchActive = !_isSearchActive;
      if (!_isSearchActive) {
        _searchDebounce?.cancel();
        _searchController.clear();
        _searchResults = [];
        _isSearching = false;
      } else {
        // Search and multi-select are mutually exclusive: selection bar actions
        // operate on _items, not search results.
        _isSelectionMode = false;
        _selectedIds.clear();
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) _searchFocusNode.requestFocus();
        });
      }
    });
  }

_PremiumizeFilesScreenState._performSear:
void _performSearch(String query) {
    final q = query.trim();
    if (q.isEmpty) {
      _searchDebounce?.cancel();
      setState(() {
        _searchResults = [];
        _isSearching = false;
      });
      return;
    }

    // Root: server-side cloud search (recursive), debounced to limit calls.
    if (_isAtRoot) {
      _searchDebounce?.cancel();
      setState(() => _isSearching = true);
      _searchDebounce = Timer(
        const Duration(milliseconds: 350),
        () => _runCloudSearch(q),
      );
      return;
    }

    // Inside a folder: filter the currently-loaded items locally.
    final lower = q.toLowerCase();
    setState(() {
      _isSearching = false;
      _searchResults = _items
          .where((i) => !i.isFolder && i.name.toLowerCase().contains(lower))
          .toList();
    });
  }

_PremiumizeFilesScreenState._runCloudSea:
Future<void> _runCloudSearch(String query) async {
    final apiKey = _apiKey;
    if (apiKey == null || apiKey.isEmpty) return;
    try {
      final results = await PremiumizeService.searchCloud(apiKey, query);
      if (!mounted) return;
      // Drop stale results if the query changed while the request was in flight.
      if (_searchController.text.trim() != query) return;
      setState(() {
        _searchResults = results;
        _isSearching = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() => _isSearching = false);
      _showSnackBar('Search failed: $e', isError: true);
    }
  }

_PremiumizeFilesScreenState._buildFileCa:
Widget _buildFileCard(
    PremiumizeFolderItem item,
    int index, {
    bool autofocusFirst = true,
  }) {
    final isVideo = item.isVideo;
    final date = _formatUnixDate(item.createdAt);
    final metaParts = <String>[
      if (!item.isFolder && item.size > 0) Formatters.formatFileSize(item.size),
      if (date.isNotEmpty) date,
    ];

    if (widget.selectSourceMode) {
      return CloudFileRow(
        kind: item.isFolder
            ? CloudRowKind.folder
            : isVideo
            ? CloudRowKind.video
            : CloudRowKind.file,
        title: item.name,
        meta: metaParts.isEmpty ? null : metaParts.join(' · '),
        onTap: (item.isFolder || isVideo)
            ? () => _selectBoundSource(item)
            : null,
        actions: item.isFolder
            ? [
                CloudRowAction(
                  icon: Icons.folder_open_rounded,
                  label: 'Browse folder',
                  onSelected: () => _navigateIntoFolder(item),
                ),
              ]
            : const [],
        focusNode: (autofocusFirst && index == 0) ? _firstItemFocusNode : null,
      );
    }

    // Same action set (labels, icons, conditions) the old Open/Play pills +
    // ⋮ menu offered; the row's tap now carries Open (folders) and Play
    // (videos).
    final actions = <CloudRowAction>[
      // Videos get a ▶ too, even though tapping the row already plays them —
      // folder rows have one, and a video row without it reads as unplayable.
      if (item.isFolder || isVideo)
        CloudRowAction(
          icon: Icons.play_arrow_rounded,
          label: 'Play',
          showInStrip: true,
          onSelected: () {
            if (item.isFolder) {
              _playFolder(item);
            } else {
              _playFile(item);
            }
          },
        ),
      CloudRowAction(
        icon: Icons.download,
        label: 'Download',
        showInStrip: true,
        onSelected: () {
          if (item.isFolder) {
            _downloadFolder(item);
          } else {
            _downloadFile(item);
          }
        },
      ),
      if (item.isFolder || isVideo)
        CloudRowAction(
          icon: Icons.playlist_add,
          label: 'Add to Playlist',
          onSelected: () => _addToPlaylist(item),
        ),
      CloudRowAction(
        icon: Icons.delete_outline,
        label: 'Delete',
        destructive: true,
        onSelected: () => _showDeleteDialog(item),
      ),
    ];

    return CloudFileRow(
      kind: item.isFolder
          ? CloudRowKind.folder
          : isVideo
          ? CloudRowKind.video
          : CloudRowKind.file,
      title: item.name,
      meta: metaParts.isEmpty ? null : metaParts.join(' · '),
      onTap: item.isFolder
          ? () => _navigateIntoFolder(item)
          : isVideo
          ? () => _playFile(item)
          : null,
      actions: actions,
      selectionMode: _isSelectionMode,
      selected: _selectedIds.contains(item.id),
      onToggleSelected: () => _toggleSelection(item.id),
      focusNode: (autofocusFirst && index == 0) ? _firstItemFocusNode : null,
    );
  }

_PremiumizeFilesScreenState._buildSearch:
Widget _buildSearchBar() {
    final app = AppThemeScope.of(context);
    final hasText = _searchController.text.isNotEmpty;
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 8, 16, 8),
      child: Row(
        children: [
          Expanded(
            child: TvTextField(
              controller: _searchController,
              focusNode: _searchFocusNode,
              textInputAction: TextInputAction.search,
              // D-pad exits for Android TV (formerly a Focus/onKeyEvent
              // wrapper): up to the app-bar actions, down into the results,
              // right to the clear button when visible.
              onUpArrow: () =>
                  _searchFocusNode.focusInDirection(TraversalDirection.up),
              onDownArrow: () =>
                  _searchFocusNode.focusInDirection(TraversalDirection.down),
              onRightArrow: hasText
                  ? () => _searchClearFocusNode.requestFocus()
                  : null,
              decoration: InputDecoration(
                hintText: _isAtRoot
                    ? 'Search your Premiumize cloud...'
                    : 'Search files...',
                prefixIcon: const Icon(Icons.search, color: Colors.grey),
                filled: true,
                fillColor: app.fade(app.core.tx, 0.06),
                border: OutlineInputBorder(
                  borderRadius: app.shape.br(8),
                  borderSide: BorderSide.none,
                ),
                contentPadding: const EdgeInsets.symmetric(
                  horizontal: 16,
                  vertical: 12,
                ),
              ),
              onChanged: _performSearch,
              onSubmitted: (_) => _searchFocusNode.unfocus(),
            ),
          ),
          if (hasText)
            Padding(
              padding: const EdgeInsets.only(left: 8),
              child: Focus(
                focusNode: _searchClearFocusNode,
                onKeyEvent: (node, event) {
                  if (event is! KeyDownEvent) return KeyEventResult.ignored;
                  final key = event.logicalKey;
                  if (isActivateKey(key)) {
                    setState(() {
                      _searchController.clear();
                      _searchResults = [];
                    });
                    _searchFocusNode.requestFocus();
                    return KeyEventResult.handled;
                  }
                  if (key == LogicalKeyboardKey.arrowLeft) {
                    _searchFocusNode.requestFocus();
                    return KeyEventResult.handled;
                  }
                  return KeyEventResult.ignored;
                },
                child: Builder(
                  builder: (context) {
                    final isFocused = Focus.of(context).hasFocus;
                    return Container(
                      decoration: BoxDecoration(
                        color: app.fade(app.core.tx, 0.06),
                        borderRadius: app.shape.br(8),
                        border: isFocused
                            ? Border.all(color: app.core.tx, width: 2)
                            : null,
                      ),
                      child: IconButton(
                        icon: const Icon(Icons.clear, color: Colors.grey),
                        onPressed: () {
                          setState(() {
                            _searchController.clear();
                            _searchResults = [];
                          });
                          _searchFocusNode.requestFocus();
                        },
                      ),
                    );
                  },
                ),
              ),
            ),
        ],
      ),
    );
  }

